#!/usr/bin/env python3
"""Materialize the strict AIP Voice candidate for off-repo qualification.

This is validation scaffolding in tempera-sdk only. It refuses to run unless the
producer branch still contains the exact expected pre-promotion app.py blob.
"""
from __future__ import annotations

import base64
import hashlib
import subprocess
import zlib
from pathlib import Path

VOICE = Path(".voice-source")
EXPECTED_BASE_APP_BLOB = "9c5d2f7303cd9c4fc186d894eee84abb3d927456"
FILES = {
    "src/tempera_voice/app.py": "",
    "src/tempera_voice/aip_agents.py": "",
}
EXPECTED_SHA256 = {
    "src/tempera_voice/app.py": "b9f2c16af09081ee7c90514d9e00ae3904068178e2e1caf70afd0c38d48423c3",
    "src/tempera_voice/aip_agents.py": "38fb9072c8985690513941d0e2a5c712dd1ba6d5a539e96b500e33d700622668",
}


def git_blob_sha(path: Path) -> str:
    return subprocess.check_output(
        ["git", "-C", str(VOICE), "hash-object", path.relative_to(VOICE).as_posix()],
        text=True,
    ).strip()


def main() -> None:
    app_path = VOICE / "src/tempera_voice/app.py"
    observed = git_blob_sha(app_path)
    if observed != EXPECTED_BASE_APP_BLOB:
        raise SystemExit(
            f"refusing drifted Voice app.py: {observed} != {EXPECTED_BASE_APP_BLOB}"
        )
    for relative, encoded in FILES.items():
        payload = zlib.decompress(base64.b64decode(encoded))
        digest = hashlib.sha256(payload).hexdigest()
        if digest != EXPECTED_SHA256[relative]:
            raise SystemExit(f"embedded {relative} digest mismatch: {digest}")
        target = VOICE / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(payload)
        print(f"materialized {relative} sha256={digest}")


if __name__ == "__main__":
    main()
